// Retains native select IDs/events behind consistently styled dropdowns.
(()=>{
 "use strict";
 let sequence=0,opened=null;const records=new Map();
 const on=(e,n,fn,o)=>e.addEventListener(n,fn,o);
 function close(focus=false){if(!opened)return;const r=opened;opened=null;r.popup.hidden=true;r.button.setAttribute("aria-expanded","false");r.button.removeAttribute("aria-activedescendant");r.typeahead="";clearTimeout(r.timer);if(focus&&r.button.isConnected)r.button.focus();}
 function labelFor(s){if(s.getAttribute("aria-label"))return s.getAttribute("aria-label");if(s.labels?.length){const c=s.labels[0].cloneNode(true);c.querySelectorAll("select,button").forEach(e=>e.remove());return c.textContent.trim()||"Choose an option";}return"Choose an option";}
 function enabled(r){return[...r.select.options].map((o,i)=>({o,i})).filter(({o})=>!o.disabled&&!o.parentElement?.disabled).map(({i})=>i);}
 function place(r){const rect=r.button.getBoundingClientRect(),margin=8,below=innerHeight-rect.bottom-margin,above=rect.top-margin,w=Math.max(0,Math.min(Math.max(rect.width,170),innerWidth-margin*2));r.popup.style.width=w+"px";r.popup.style.left=Math.max(margin,Math.min(rect.left,innerWidth-w-margin))+"px";const up=below<150&&above>below;r.popup.style.maxHeight=Math.max(44,Math.min(280,up?above-6:below-6))+"px";r.popup.style.top=Math.max(margin,up?rect.top-r.popup.offsetHeight-6:rect.bottom+6)+"px";}
 function setActive(r,index,scroll=true){const list=enabled(r);if(!list.length){r.active=-1;return;}r.active=list.includes(index)?index:list[0];[...r.popup.children].forEach((e,i)=>e.classList.toggle("is-active",i===r.active));const e=r.popup.children[r.active];if(e){r.button.setAttribute("aria-activedescendant",e.id);if(scroll)e.scrollIntoView({block:"nearest"});}}
 function choose(r,i){const o=r.select.options[i];if(!o||o.disabled||o.parentElement?.disabled)return;const changed=r.select.selectedIndex!==i;r.select.selectedIndex=i;close(true);sync(r);if(changed){r.select.dispatchEvent(new Event("input",{bubbles:true}));r.select.dispatchEvent(new Event("change",{bubbles:true}));}}
 function renderOptions(r){r.popup.replaceChildren();[...r.select.options].forEach((o,i)=>{const e=document.createElement("li");e.id=r.id+"-option-"+i;e.className="notepad-select-option";e.setAttribute("role","option");e.setAttribute("aria-selected",String(i===r.select.selectedIndex));const disabled=o.disabled||o.parentElement?.disabled;e.setAttribute("aria-disabled",String(!!disabled));const text=document.createElement("span"),check=document.createElement("span");text.textContent=o.label||o.textContent;check.className="notepad-select-check";check.setAttribute("aria-hidden","true");check.textContent=i===r.select.selectedIndex?"✓":"";e.append(text,check);on(e,"pointerdown",event=>event.preventDefault());on(e,"click",()=>choose(r,i));on(e,"pointermove",()=>{if(!disabled)setActive(r,i,false);});r.popup.append(e);});}
 function sync(r){if(!r.select.isConnected){if(opened===r)close();r.observer.disconnect();r.popup.remove();records.delete(r.select);return;}const o=r.select.options[r.select.selectedIndex];r.text.textContent=o?(o.label||o.textContent):"Choose…";r.button.disabled=r.select.disabled;if(opened===r){renderOptions(r);setActive(r,r.active,false);place(r);}}
 function open(r){if(r.button.disabled)return;if(opened===r){close(true);return;}close();opened=r;renderOptions(r);r.popup.hidden=false;r.button.setAttribute("aria-expanded","true");place(r);setActive(r,r.select.selectedIndex);}
 function enhance(s){if(records.has(s)||s.multiple||s.size>1)return;const name=labelFor(s),id="notepad-dropdown-"+(++sequence),p=s.parentElement;if(p.tagName==="LABEL"&&p.querySelectorAll("input,select,textarea").length===1){const f=document.createElement("div"),caption=document.createElement("span");f.className="notepad-select-field";caption.className="notepad-select-caption";caption.textContent=name;p.before(f);f.append(caption,s);p.remove();}const wrapper=document.createElement("div");wrapper.className="notepad-select";wrapper.dataset.nativeId=s.id;s.before(wrapper);wrapper.append(s);s.classList.add("notepad-native");s.tabIndex=-1;s.setAttribute("aria-hidden","true");const b=document.createElement("button");b.type="button";b.className="notepad-select-trigger";b.setAttribute("role","combobox");b.setAttribute("aria-haspopup","listbox");b.setAttribute("aria-expanded","false");b.setAttribute("aria-controls",id);b.setAttribute("aria-label",name);const text=document.createElement("span"),arrow=document.createElement("span");text.className="notepad-select-text";arrow.className="notepad-select-arrow";arrow.setAttribute("aria-hidden","true");b.append(text,arrow);wrapper.append(b);const popup=document.createElement("ul");popup.id=id;popup.className="notepad-select-popup";popup.setAttribute("role","listbox");popup.setAttribute("aria-label",name);popup.hidden=true;document.body.append(popup);const r={select:s,wrapper,button:b,text,popup,id,active:0,typeahead:"",timer:null,observer:null};records.set(s,r);r.observer=new MutationObserver(()=>sync(r));r.observer.observe(s,{childList:true,subtree:true,attributes:true,characterData:true});on(s,"change",()=>sync(r));on(b,"click",()=>open(r));on(b,"keydown",e=>{const list=enabled(r);if(!list.length)return;if(e.key==="Escape"&&opened===r){e.preventDefault();close(true);return;}if(e.key==="Tab"){close();return;}if(e.key==="Enter"||e.key===" "){if(e.key===" "&&r.typeahead)return;e.preventDefault();if(opened===r)choose(r,r.active);else open(r);return;}if(["ArrowDown","ArrowUp","Home","End"].includes(e.key)){e.preventDefault();if(opened!==r)open(r);const pos=list.indexOf(r.active),next=e.key==="Home"?list[0]:e.key==="End"?list[list.length-1]:list[Math.max(0,Math.min(list.length-1,pos+(e.key==="ArrowDown"?1:-1)))];setActive(r,next);return;}if(e.key.length===1&&!e.ctrlKey&&!e.metaKey&&!e.altKey){e.preventDefault();if(opened!==r)open(r);r.typeahead+=e.key.toLocaleLowerCase();clearTimeout(r.timer);r.timer=setTimeout(()=>r.typeahead="",700);const i=list.find(i=>(s.options[i].label||s.options[i].textContent).toLocaleLowerCase().startsWith(r.typeahead));if(i!==undefined)setActive(r,i);}});sync(r);}
 document.querySelectorAll("select").forEach(enhance);
 on(document,"pointerdown",e=>{if(opened&&!opened.wrapper.contains(e.target)&&!opened.popup.contains(e.target))close();});on(window,"resize",()=>{if(opened)place(opened);});on(document,"scroll",e=>{if(opened&&!opened.popup.contains(e.target))place(opened);},true);on(document,"change",()=>requestAnimationFrame(()=>records.forEach(sync)));
 // Hide detached popups when their associated editor or filter section is hidden.
 new MutationObserver(()=>{if(opened&&!opened.button.getClientRects().length)close();}).observe(document.querySelector("main"),{attributes:true,subtree:true,attributeFilter:["class"]});
})();
